import{_ as t,o as e,c as i,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-11-05（材料 · 三轴「分子编织」把二维编织布从双轴推进到三轴）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-11-05-materials.md","filePath":"topics/materials/science-daily-2026-11-05-materials.md"}'),r={name:"topics/materials/science-daily-2026-11-05-materials.md"};function a(n,o,l,c,d,g){return e(),i("div",null,[...o[0]||(o[0]=[s('<h1 id="科学日报-·-2026-11-05-材料-·-三轴「分子编织」把二维编织布从双轴推进到三轴" tabindex="-1">科学日报 · 2026-11-05（材料 · 三轴「分子编织」把二维编织布从双轴推进到三轴） <a class="header-anchor" href="#科学日报-·-2026-11-05-材料-·-三轴「分子编织」把二维编织布从双轴推进到三轴" aria-label="Permalink to &quot;科学日报 · 2026-11-05（材料 · 三轴「分子编织」把二维编织布从双轴推进到三轴）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> — 第55期 ｜ 科学板块（材料向 1 篇） 落盘说明：文件名带 <code>-materials</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-05-材料-·-1-1-c3-对称大环-配位-b–n-聚合——造出拓扑手性的二维三轴分子编织网络" tabindex="-1">科学日报 2026-11-05（材料 · 1/1）：C₃ 对称大环 + 配位 B–N 聚合——造出拓扑手性的二维三轴分子编织网络 <a class="header-anchor" href="#科学日报-2026-11-05-材料-·-1-1-c3-对称大环-配位-b–n-聚合——造出拓扑手性的二维三轴分子编织网络" aria-label="Permalink to &quot;科学日报 2026-11-05（材料 · 1/1）：C₃ 对称大环 + 配位 B–N 聚合——造出拓扑手性的二维三轴分子编织网络&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> ｜ DOI: 10.1038/s41586-026-11218-8 ｜ Nature (2026)</p></blockquote><ul><li>问题：<strong>分子编织（molecular weaving）</strong> 把分子链交织成<strong>有序网络</strong>，是设计<strong>功能材料</strong>的有力策略；但此前主要依赖<strong>线性构筑单元</strong>与<strong>双轴（biaxial）结构</strong>，<strong>≥3 轴的高阶编织</strong>在<strong>构建与物性研究</strong>上长期未被充分探索。</li><li>方法：以 <strong>C₃ 对称大环</strong>作<strong>非线性构筑单元</strong>，通过<strong>配位 B–N 聚合（dative B–N polymerization）</strong> 把它引入编织结构，构建<strong>二维网状三轴（triaxial）编织聚合物网络</strong>。</li><li>结果（实测）： <ul><li>该材料呈现独特的<strong>拓扑手性（topological chirality）<strong>与</strong>稳健的力学性能</strong>；</li><li>作为<strong>多孔材料</strong>，可<strong>分离代表性芳香族/脂肪族化合物</strong>；</li><li>作者据此论证<strong>高阶三轴编织拓扑</strong>在<strong>调控材料性质</strong>上提供独特优势，为功能材料构造<strong>引入一个额外的拓扑维度</strong>。</li></ul></li><li>洞察（对本库 <code>materials</code> × <code>physics</code>）： <ol><li><strong>「把『自由度』从化学（换成什么原子）挪到拓扑（怎么织）」</strong>——同样是大环/聚合物，<strong>编织轴数</strong>本身成了可设计自由度；判据：<strong>当化学组成的调节空间趋于饱和时，去问『同样的积木还能以哪几种拓扑方式拼』</strong>（呼应母题「<strong>把设计自由嵌到物理层/结构层</strong>」，与 <code>topics/materials/science-daily-2026-11-03-materials.md</code> 的「1D 织成 2D」同族，本期是「2 轴织到 3 轴」的同一母题延续）。</li><li><strong>「拓扑手性 = 由编织方式而非手性中心带来的手性」</strong>——手性来源从<strong>分子手性中心</strong>切换到<strong>网络拓扑</strong>，可望带来<strong>新一类的对映选择性/分离</strong>能力（本例已能分离芳香/脂肪族化合物）；判据：<strong>当需要手性功能时，先问『手性能不能来自排列方式而非分子本身』</strong>。</li><li><strong>与库内呼应</strong>：与 <code>topics/materials/</code> 的 MXene/钙钛矿/离子电子忆阻突触等「<strong>用结构而非成分造功能</strong>」一脉相承。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ <code>topics/physics/index.md</code> ｜ 第55期 科学板块</p></blockquote><p>关键词：科学日报第55期、分子编织molecular weaving、三轴编织triaxial weave、二维网状编织聚合物、C3对称大环、配位B–N聚合dative B–N polymerization、拓扑手性topological chirality、稳健力学性能、多孔材料、芳香族脂肪族化合物分离、额外拓扑维度、高阶编织≥3轴、非线性构筑单元、把设计自由嵌到结构层、拓扑而非化学来源的手性、结构造功能、从双轴到三轴、约束涌现、改路径优于加力度</p><p>关联：<code>topics/materials/index.md</code>、<code>topics/materials/science-daily-2026-11-04-materials.md</code>、<code>topics/materials/science-daily-2026-11-03-materials.md</code>、<code>topics/physics/index.md</code>、<code>ScienceDaily/daily/2026-11-05.md</code></p>',10)])])}const u=t(r,[["render",a]]);export{p as __pageData,u as default};
